import numpy as np
from scirel.kinetic import assemble_molecular_hydrogen_collision_matrices
result = assemble_molecular_hydrogen_collision_matrices(
    vr=np.array([0.5, 1.0]), vx=np.array([-1.0, 1.0]),
    Vr2pidVr=np.array([1.7671458676442586, 3.141592653589793]),
    dVx=np.array([2.0, 2.0]), Tnorm=1.0, mu=1.0,
)
assert set(result) >= {"SIG_CX", "SIG_H2_H", "SIG_H2_P", "SIG_H2_H2"}
assert result["SIG_CX"].shape == (4, 4)
assert np.all(result["SIG_CX"] >= 0.0)
try:
    assemble_molecular_hydrogen_collision_matrices(
        np.array([0.5, 1.0]), np.array([-1.0, 1.0]),
        np.array([1.0]), np.array([2.0, 2.0]), 1.0,
    )
except ValueError:
    pass
else:
    raise AssertionError("a carrier length mismatch must be rejected")
